pub fn canonical_qm31(x: QM31) -> QM31 {
    QM31 {
        c0: CM31 {
            a: M31(ct::reduce64(x.c0.a.0 as u64)),
            b: M31(ct::reduce64(x.c0.b.0 as u64)),
        },
        c1: CM31 {
            a: M31(ct::reduce64(x.c1.a.0 as u64)),
            b: M31(ct::reduce64(x.c1.b.0 as u64)),
        },
    }
}
